28	constexpr size_t KV_DIM_NUM = 4;
29	constexpr size_t K_CACHE_DIM_NUM = 4;
30	constexpr size_t CKV_CACHE_DIM_NUM = 4;
31	
32	const std::initializer_list<DataType> KV_DTYPE_SUPPORT_LIST = {DataType::DT_FLOAT16, DataType::DT_BF16};
33	const std::initializer_list<DataType> CACHE_DTYPE_SUPPORT_LIST = {
34	    DataType::DT_FLOAT16, DataType::DT_BF16, DataType::DT_INT8, DataType::DT_FLOAT8_E4M3FN, DataType::DT_HIFLOAT8};
35	const std::initializer_list<DataType> INDEX_DTYPE_SUPPORT_LIST = {DataType::DT_INT64};
