37	aclnnStatus CheckAiInfraKvRmsNormRopeCacheParams(
38	    const aclTensor* kv, const aclTensor* gamma, const aclTensor* cos, const aclTensor* sin, const aclTensor* index,
39	    aclTensor* kCacheRef, aclTensor* ckvCacheRef, char* cacheMode, char* rotaryMode, char* quantMode,
40	    const aclTensor* kRopeOut, const aclTensor* cKvOut)
41	{
42	    OP_CHECK_NULL(kv, return ACLNN_ERR_INNER_NULLPTR);
43	    OP_CHECK_NULL(gamma, return ACLNN_ERR_INNER_NULLPTR);
44	    OP_CHECK_NULL(cos, return ACLNN_ERR_INNER_NULLPTR);
45	    OP_CHECK_NULL(sin, return ACLNN_ERR_INNER_NULLPTR);
46	    OP_CHECK_NULL(index, return ACLNN_ERR_INNER_NULLPTR);
47	    OP_CHECK_NULL(ckvCacheRef, return ACLNN_ERR_INNER_NULLPTR);
48	    OP_CHECK_NULL(kRopeOut, return ACLNN_ERR_INNER_NULLPTR);
49	    OP_CHECK_NULL(cKvOut, return ACLNN_ERR_INNER_NULLPTR);
50	    OP_CHECK_NULL(cacheMode, return ACLNN_ERR_INNER_NULLPTR);
51	    OP_CHECK_NULL(rotaryMode, return ACLNN_ERR_INNER_NULLPTR);
52	    OP_CHECK_NULL(quantMode, return ACLNN_ERR_INNER_NULLPTR);
53	
54	    OP_CHECK_WRONG_DIMENSION(kv, KV_DIM_NUM, return ACLNN_ERR_PARAM_INVALID);
55	    OP_CHECK_WRONG_DIMENSION(ckvCacheRef, CKV_CACHE_DIM_NUM, return ACLNN_ERR_PARAM_INVALID);
56	
57	    OP_CHECK_DTYPE_NOT_SUPPORT(kv, KV_DTYPE_SUPPORT_LIST, return ACLNN_ERR_PARAM_INVALID);
58	    OP_CHECK_DTYPE_NOT_SUPPORT(gamma, KV_DTYPE_SUPPORT_LIST, return ACLNN_ERR_PARAM_INVALID);
59	    OP_CHECK_DTYPE_NOT_SUPPORT(cos, KV_DTYPE_SUPPORT_LIST, return ACLNN_ERR_PARAM_INVALID);
60	    OP_CHECK_DTYPE_NOT_SUPPORT(sin, KV_DTYPE_SUPPORT_LIST, return ACLNN_ERR_PARAM_INVALID);
61	    OP_CHECK_DTYPE_NOT_SUPPORT(index, INDEX_DTYPE_SUPPORT_LIST, return ACLNN_ERR_PARAM_INVALID);
62	    OP_CHECK_DTYPE_NOT_SUPPORT(ckvCacheRef, CACHE_DTYPE_SUPPORT_LIST, return ACLNN_ERR_PARAM_INVALID);
63	    if (kCacheRef != nullptr) {
64	        OP_CHECK_NULL(kCacheRef, return ACLNN_ERR_INNER_NULLPTR);
65	        OP_CHECK_WRONG_DIMENSION(kCacheRef, K_CACHE_DIM_NUM, return ACLNN_ERR_PARAM_INVALID);
66	        OP_CHECK_DTYPE_NOT_SUPPORT(kCacheRef, CACHE_DTYPE_SUPPORT_LIST, return ACLNN_ERR_PARAM_INVALID);
67	    }
68	    return ACLNN_SUCCESS;
69	}
