71	static aclnnStatus AiInfraKvRmsNormRopeCacheCommonProcess(
72	    const aclTensor* kv, const aclTensor* gamma, const aclTensor* cos, const aclTensor* sin, const aclTensor* index,
73	    aclTensor* kCacheRef, aclTensor* ckvCacheRef, const aclTensor* kRopeScale, const aclTensor* cKvScale,
74	    const aclTensor* kRopeOffset, const aclTensor* cKvOffset, const aclTensor* v, double epsilon, char* cacheMode,
75	    char* rotaryMode, char* quantMode, bool isOutputKv, const aclTensor* kRopeOut, const aclTensor* cKvOut,
76	    aclOpExecutor* executor)
77	{
78	    auto ret = CheckAiInfraKvRmsNormRopeCacheParams(
79	        kv, gamma, cos, sin, index, kCacheRef, ckvCacheRef, cacheMode, rotaryMode, quantMode, kRopeOut,
80	        cKvOut);
81	    CHECK_RET(ret == ACLNN_SUCCESS, ret);
82	
83	    const aclTensor* kvFinal = l0op::Contiguous(kv, executor);
84	    CHECK_COND(kvFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous kv failed.");
85	    const aclTensor* gammaFinal = l0op::Contiguous(gamma, executor);
86	    CHECK_COND(gammaFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous gamma failed.");
87	    const aclTensor* cosFinal = l0op::Contiguous(cos, executor);
88	    CHECK_COND(cosFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous cos failed.");
89	    const aclTensor* sinFinal = l0op::Contiguous(sin, executor);
90	    CHECK_COND(sinFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous sin failed.");
91	    const aclTensor* indexFinal = l0op::Contiguous(index, executor);
92	    CHECK_COND(indexFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous index failed.");
93	
94	    aclTensor* kCacheFinal = nullptr;
95	    if (kCacheRef != nullptr) {
96	        kCacheFinal = executor->CreateView(
97	            kCacheRef, kCacheRef->GetViewShape(), kCacheRef->GetStorageShape(), kCacheRef->GetViewStrides(),
98	            kCacheRef->GetViewOffset());
99	        CHECK_COND(kCacheFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "CreateView for kCacheRef failed.");
100	    } else {
101	        std::vector<int64_t> emptyShape = {0};
102	        aclDataType dtype = static_cast<aclDataType>(kvFinal->GetDataType());
103	        kCacheFinal = aclCreateTensor(
104	            emptyShape.data(), // view_dims: shape {0}
105	            emptyShape.size(), // view_dims_num: 1
106	            dtype,             // data_type
107	            nullptr,           // stride: nullptr 表示连续
108	            0,                 // offset: 0
109	            ACL_FORMAT_ND,     // format
110	            emptyShape.data(), // storage_dims: 同 view_dims
111	            emptyShape.size(), // storage_dims_num: 1
112	            nullptr            // tensor_data: 无实际数据
113	        );
114	    }
115	    aclTensor* ckvCacheFinal = executor->CreateView(
116	        ckvCacheRef, ckvCacheRef->GetViewShape(), ckvCacheRef->GetStorageShape(), ckvCacheRef->GetViewStrides(),
117	        ckvCacheRef->GetViewOffset());
118	    CHECK_COND(ckvCacheFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "CreateView for ckvCacheRef failed.");
119	
120	    // 处理可选参数
121	    const aclTensor* kRopeScaleFinal = nullptr;
122	    if (kRopeScale != nullptr) {
123	        kRopeScaleFinal = l0op::Contiguous(kRopeScale, executor);
124	        CHECK_COND(kRopeScale != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous kRopeScale failed.");
125	    }
126	    const aclTensor* cKvScaleFinal = nullptr;
127	    if (cKvScale != nullptr) {
128	        cKvScaleFinal = l0op::Contiguous(cKvScale, executor);
129	        CHECK_COND(cKvScaleFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous cKvScale failed.");
130	    }
131	    const aclTensor* kRopeOffsetFinal = nullptr;
132	    if (kRopeOffset != nullptr) {
133	        kRopeOffsetFinal = l0op::Contiguous(kRopeOffset, executor);
134	        CHECK_COND(kRopeOffsetFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous kRopeOffset failed.");
135	    }
136	    const aclTensor* cKvOffsetFinal = nullptr;
137	    if (cKvOffset != nullptr) {
138	        cKvOffsetFinal = l0op::Contiguous(cKvOffset, executor);
139	        CHECK_COND(cKvOffsetFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous cKvOffset failed.");
140	    }
141	    const aclTensor* vFinal = nullptr;
142	    if (v != nullptr) {
143	        vFinal = l0op::Contiguous(v, executor);
144	        CHECK_COND(vFinal != nullptr, ACLNN_ERR_INNER_NULLPTR, "Contiguous v failed.");
145	    }
146	
147	    // out is always contiguous. passed directly to l0op.
148	    bool out = l0op::AiInfraKvRmsNormRopeCache(
149	        kvFinal, gammaFinal, cosFinal, sinFinal, indexFinal, kCacheFinal, ckvCacheFinal, kRopeScaleFinal,
150	        cKvScaleFinal, kRopeOffsetFinal, cKvOffsetFinal, vFinal, epsilon, cacheMode, rotaryMode, quantMode,
151	        isOutputKv, kRopeOut, cKvOut, executor);
152	    CHECK_RET(out, ACLNN_ERR_INNER_NULLPTR);
153	
154	    return ACLNN_SUCCESS;
155	}
156	
157	aclnnStatus aclnnAiInfraKvRmsNormRopeCacheGetWorkspaceSize(
158	    const aclTensor* kv, const aclTensor* gamma, const aclTensor* cos, const aclTensor* sin, const aclTensor* index,
159	    aclTensor* kCacheRef, aclTensor* ckvCacheRef, const aclTensor* kRopeScaleOptional,
160	    const aclTensor* ckvScaleOptional, const aclTensor* kRopeOffsetOptional, const aclTensor* cKvOffsetOptional,
161	    const aclTensor* vOptional, double epsilon, char* cacheModeOptional, char* rotaryModeOptional,
162	    char* quantModeOptional, bool isOutputKv, aclTensor* kRopeOut, aclTensor* cKvOut, uint64_t* workspaceSize,
163	    aclOpExecutor** executor)
164	{
165	    L2_DFX_PHASE_1(
166	        aclnnAiInfraKvRmsNormRopeCache,
167	        DFX_IN(
168	            kv, gamma, cos, sin, index, kCacheRef, ckvCacheRef, kRopeScaleOptional, ckvScaleOptional,
169	            kRopeOffsetOptional, cKvOffsetOptional, vOptional),
170	        DFX_OUT(kRopeOut, cKvOut));
171	
172	    auto uniqueExecutor = CREATE_EXECUTOR();
173	    auto ret = AiInfraKvRmsNormRopeCacheCommonProcess(
174	        kv, gamma, cos, sin, index, kCacheRef, ckvCacheRef, kRopeScaleOptional, ckvScaleOptional, kRopeOffsetOptional,
175	        cKvOffsetOptional, vOptional, epsilon, cacheModeOptional, rotaryModeOptional, quantModeOptional, isOutputKv,
176	        kRopeOut, cKvOut, uniqueExecutor.get());
177	    CHECK_RET(ret == ACLNN_SUCCESS, ret);
178	
179	    *workspaceSize = uniqueExecutor->GetWorkspaceSize();
180	    uniqueExecutor.ReleaseTo(executor);
181	    return ACLNN_SUCCESS;
182	}
183	
184	aclnnStatus aclnnAiInfraKvRmsNormRopeCache(
185	    void* workspace, uint64_t workspaceSize, aclOpExecutor* executor, aclrtStream stream)
186	{
187	    L2_DFX_PHASE_2(aclnnAiInfraKvRmsNormRopeCache);
188	    return CommonOpExecutorRun(workspace, workspaceSize, executor, stream);
189	}
190	
191	} // namespace
