58	bool AiInfraKvRmsNormRopeCacheTilingDs::IsB1SD(const gert::TilingContext* const context)
59	{
60	    // Tiling strategy decision between 'CutT' and 'CutB'.
61	    auto kvShapeTuple = GetShapeTuple(context, KV_INDEX);
62	    int64_t seqLen = std::get<SHAPE_IDX_S>(kvShapeTuple);
63	
64	    bool sAligned = (seqLen == this->ropeSeqLength);
65	
66	    if (sAligned) {
67	        // CutT is available as the most effective tiling method.
68	        // sAligned: Each single batch (B) has a unique rope factor sequence, where 'S_kv = S_rope'.
69	        return true;
70	    } else {
71	        // No need to reload rope factors upon processing a new batch, where parallel procession among multiple batches
72	        // with same S index is available.
73	
74	        // MTP definition could be valid ONLY when 'Skv>Srope = 1'.
75	        this->isMTP_ = (seqLen > 1);
76	        return false;
77	    }
78	}
