80	bool AiInfraKvRmsNormRopeCacheTilingDs::CheckScaleValid(const gert::TilingContext* const context)
81	{
82	    auto scale1Shape = context->GetOptionalInputShape(K_ROPE_SCALE_IDX);
83	    auto scale2Shape = context->GetOptionalInputShape(C_KV_SCALE_IDX);
84	
85	    bool isValid = true;
86	    isValid = isValid && ((scale1Shape != nullptr) || (scale2Shape != nullptr));
87	    if ((scale1Shape != nullptr) && (scale2Shape != nullptr)) {
88	        isValid = isValid && (scale1Shape->GetStorageShape().GetDimNum() == scale2Shape->GetStorageShape().GetDimNum());
89	    }
90	    isValid = isValid && (((scale1Shape != nullptr) && (scale1Shape->GetStorageShape().GetDimNum() <= DIM_TWO)) ||
91	                          ((scale2Shape != nullptr) && (scale2Shape->GetStorageShape().GetDimNum() <= DIM_TWO)));
92	    if (!isValid) {
93	        return false;
94	    }
95	    if (methodMode_ == 0) {
96	        if (scale1Shape != nullptr && scale1Shape->GetStorageShape().GetDimNum() == DIM_ONE) {
97	            isValid = isValid && (scale1Shape->GetStorageShape().GetDim(0) == ROPE_LENGTH);
98	        }
99	
100	        if (scale1Shape != nullptr && scale1Shape->GetStorageShape().GetDimNum() == DIM_TWO) {
101	            isValid = isValid && (scale1Shape->GetStorageShape().GetDim(0) == DIM_ONE);
102	            isValid = isValid && (scale1Shape->GetStorageShape().GetDim(1) == ROPE_LENGTH);
103	        }
104	
105	        if (scale2Shape != nullptr && scale2Shape->GetStorageShape().GetDimNum() == DIM_ONE) {
106	            isValid = isValid && (scale2Shape->GetStorageShape().GetDim(0) == RMS_NORM_LENGTH);
107	        }
108	
109	        if (scale2Shape != nullptr && scale2Shape->GetStorageShape().GetDimNum() == DIM_TWO) {
110	            isValid = isValid && (scale2Shape->GetStorageShape().GetDim(0) == DIM_ONE);
111	            isValid = isValid && (scale2Shape->GetStorageShape().GetDim(1) == RMS_NORM_LENGTH);
112	        }
113	    } else {
114	        if (scale1Shape != nullptr && scale1Shape->GetStorageShape().GetDimNum() == DIM_ONE) {
115	            isValid = isValid && (scale1Shape->GetStorageShape().GetDim(0) == RMS_NORM_LENGTH);
116	        }
117	
118	        if (scale1Shape != nullptr && scale1Shape->GetStorageShape().GetDimNum() == DIM_TWO) {
119	            isValid = isValid && (scale1Shape->GetStorageShape().GetDim(0) == tilingData_.get_numHead());
120	            isValid = isValid && (scale1Shape->GetStorageShape().GetDim(1) == RMS_NORM_LENGTH);
121	        }
122	
123	        if (scale2Shape != nullptr && scale2Shape->GetStorageShape().GetDimNum() == DIM_ONE) {
124	            isValid = isValid && (scale2Shape->GetStorageShape().GetDim(0) == V_LENGTH);
125	        }
126	
127	        if (scale2Shape != nullptr && scale2Shape->GetStorageShape().GetDimNum() == DIM_TWO) {
128	            isValid = isValid && (scale2Shape->GetStorageShape().GetDim(0) == tilingData_.get_numHead());
129	            isValid = isValid && (scale2Shape->GetStorageShape().GetDim(1) == V_LENGTH);
130	        }
131	    }
132	
133	    return isValid;
134	}
