136	bool AiInfraKvRmsNormRopeCacheTilingDs::CheckOffsetValid(const gert::TilingContext* const context)
137	{
138	    auto offset1Shape = context->GetOptionalInputShape(K_ROPE_OFFSET_IDX);
139	    auto offset2Shape = context->GetOptionalInputShape(C_KV_OFFSET_IDX);
140	
141	    bool isValid = true;
142	    isValid = isValid && ((offset1Shape != nullptr) || (offset2Shape != nullptr));
143	    if ((offset1Shape != nullptr) && (offset2Shape != nullptr)) {
144	        isValid =
145	            isValid && (offset1Shape->GetStorageShape().GetDimNum() == offset2Shape->GetStorageShape().GetDimNum());
146	    }
147	    isValid = isValid && (((offset1Shape != nullptr) && (offset1Shape->GetStorageShape().GetDimNum() <= DIM_TWO)) ||
148	                          ((offset2Shape != nullptr) && (offset2Shape->GetStorageShape().GetDimNum() <= DIM_TWO)));
149	    if (!isValid) {
150	        return false;
151	    }
152	    if (methodMode_ == 0) {
153	        if (offset1Shape != nullptr && offset1Shape->GetStorageShape().GetDimNum() == DIM_ONE) {
154	            isValid = isValid && (offset1Shape->GetStorageShape().GetDim(0) == ROPE_LENGTH);
155	        }
156	
157	        if (offset1Shape != nullptr && offset1Shape->GetStorageShape().GetDimNum() == DIM_TWO) {
158	            isValid = isValid && (offset1Shape->GetStorageShape().GetDim(0) == DIM_ONE);
159	            isValid = isValid && (offset1Shape->GetStorageShape().GetDim(1) == ROPE_LENGTH);
160	        }
161	
162	        if (offset2Shape != nullptr && offset2Shape->GetStorageShape().GetDimNum() == DIM_ONE) {
163	            isValid = isValid && (offset2Shape->GetStorageShape().GetDim(0) == RMS_NORM_LENGTH);
164	        }
165	
166	        if (offset2Shape != nullptr && offset2Shape->GetStorageShape().GetDimNum() == DIM_TWO) {
167	            isValid = isValid && (offset2Shape->GetStorageShape().GetDim(0) == DIM_ONE);
168	            isValid = isValid && (offset2Shape->GetStorageShape().GetDim(1) == RMS_NORM_LENGTH);
169	        }
170	    } else {
171	        if (offset1Shape != nullptr && offset1Shape->GetStorageShape().GetDimNum() == DIM_ONE) {
172	            isValid = isValid && (offset1Shape->GetStorageShape().GetDim(0) == RMS_NORM_LENGTH);
173	        }
174	
175	        if (offset1Shape != nullptr && offset1Shape->GetStorageShape().GetDimNum() == DIM_TWO) {
176	            isValid = isValid && (offset1Shape->GetStorageShape().GetDim(0) == tilingData_.get_numHead());
177	            isValid = isValid && (offset1Shape->GetStorageShape().GetDim(1) == RMS_NORM_LENGTH);
178	        }
179	
180	        if (offset2Shape != nullptr && offset2Shape->GetStorageShape().GetDimNum() == DIM_ONE) {
181	            isValid = isValid && (offset2Shape->GetStorageShape().GetDim(0) == V_LENGTH);
182	        }
183	
184	        if (offset2Shape != nullptr && offset2Shape->GetStorageShape().GetDimNum() == DIM_TWO) {
185	            isValid = isValid && (offset2Shape->GetStorageShape().GetDim(0) == tilingData_.get_numHead());
186	            isValid = isValid && (offset2Shape->GetStorageShape().GetDim(1) == V_LENGTH);
187	        }
188	    }
189	    return isValid;
190	}
