192	ge::graphStatus AiInfraKvRmsNormRopeCacheTilingDs::ValidateStaticQuantMode(const gert::TilingContext* const context)
193	{
194	    // Validate Quant mode availability
195	    if (methodMode_ == 0) {
196	        OP_CHECK_IF(
197	            (currentCacheMode_ == CacheMode::NORM) && (quantMode_ != NON_QUANT_MODE),
198	            OP_LOGE(context_->GetNodeName(), "Static Quant is NOT available for CacheMode::NORM!"),
199	            return ge::GRAPH_FAILED);
200	        OP_CHECK_IF(
201	            (this->inputQuantMode_ != QuantClass::NONE && quantMode_ > QUANT_MODE),
202	            OP_LOGE(context_->GetNodeName(), "Only Support SYMMETRIC_QUANT or NON_QUANT."), return ge::GRAPH_FAILED);
203	    } else {
204	        OP_CHECK_IF(
205	            !(quantMode_ >= NON_QUANT_MODE && quantMode_ <= ASYM_QUANT_MODE),
206	            OP_LOGE(context_->GetNodeName(), "Only Support SYMMETRIC_QUANT, ASYM_QUANT_MODE or NON_QUANT."),
207	            return ge::GRAPH_FAILED);
208	    }
209	
210	    // Validate quant tensors
211	    if (quantMode_ == QUANT_MODE) {
212	        OP_CHECK_IF(
213	            !CheckScaleValid(context_), OP_LOGE(context_->GetNodeName(), "Static Quant: scale shape check failed."),
214	            return ge::GRAPH_FAILED);
215	    }
216	
217	    if ((quantMode_ > QUANT_MODE)) {
218	        OP_CHECK_IF(
219	            !CheckOffsetValid(context_), OP_LOGE(context_->GetNodeName(), "Static Quant: offset shape check failed."),
220	            return ge::GRAPH_FAILED);
221	    }
222	
223	    return ge::GRAPH_SUCCESS;
224	}
