250	ge::graphStatus AiInfraKvRmsNormRopeCacheTilingDs::SetupQuantClass(const gert::TilingContext* const context)
251	{
252	    // Update genuine static quant mode
253	    this->quantMode_ =
254	        (this->kStaticQuantMode > this->vStaticQuantMode) ? this->kStaticQuantMode : this->vStaticQuantMode;
255	
256	    auto attrs = context_->GetAttrs();
257	    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs);
258	
259	    const char* tmpInputQuantMode = attrs->GetStr(INPUT_QUANT_MODE_IDX);
260	    if (tmpInputQuantMode != nullptr) {
261	        std::string inputQuantMode = tmpInputQuantMode;
262	        std::unordered_map<std::string, QuantClass> inputQuantModeMap = {
263	            {"none", QuantClass::NONE}, {"static", QuantClass::STATIC}, {"pertile128", QuantClass::PERTILE_128}};
264	        auto it = inputQuantModeMap.find(inputQuantMode);
265	        inputQuantMode_ = (it != inputQuantModeMap.end()) ? it->second : QuantClass::STATIC;
266	    } else {
267	        inputQuantMode_ = QuantClass::NONE;
268	    }
269	
270	    // Validate: when quant_mode="none", scale/offset must be null
271	    if (inputQuantMode_ == QuantClass::NONE) {
272	        auto kRopeScaleShape = context_->GetOptionalInputShape(K_ROPE_SCALE_IDX);
273	        OP_CHECK_IF(kRopeScaleShape != nullptr, OP_LOGE(context_, "k_rope_scale is not None"), 
274	        return ge::GRAPH_FAILED);
275	
276	        auto cKvScaleShape = context_->GetOptionalInputShape(C_KV_SCALE_IDX);
277	        OP_CHECK_IF(cKvScaleShape != nullptr, OP_LOGE(context_, "c_kv_scale is not None"), 
278	        return ge::GRAPH_FAILED);
279	
280	        auto kRopeOffsetShape = context_->GetOptionalInputShape(K_ROPE_OFFSET_IDX);
281	        OP_CHECK_IF(
282	            kRopeOffsetShape != nullptr, OP_LOGE(context_, "k_rope_offset is not None"), 
283	            return ge::GRAPH_FAILED);
284	
285	        auto cKvOffsetShape = context_->GetOptionalInputShape(C_KV_OFFSET_IDX);
286	        OP_CHECK_IF(cKvOffsetShape != nullptr, OP_LOGE(context_, "c_kv_offset is not None"), 
287	        return ge::GRAPH_FAILED);
288	    }
289	
290	    // Quant branch compatibility
291	    if (inputQuantMode_ == QuantClass::STATIC && this->quantMode_ == NON_QUANT_MODE) {
292	        // Reduce static quant with no available quant terms into QuantClass::NONE
293	        inputQuantMode_ = QuantClass::NONE;
294	    }
295	
296	    // Allocate quantmode index
297	    tilingData_.set_quantClass(static_cast<int64_t>(this->inputQuantMode_));
298	    // Static QuantModes in : 0(None), 1(static symmetric), 2(static asymmetric)
299	    tilingData_.set_isKQuant(this->kStaticQuantMode);
300	    tilingData_.set_isVQuant(this->vStaticQuantMode);
301	    return ge::GRAPH_SUCCESS;
302	}
