304	ge::graphStatus AiInfraKvRmsNormRopeCacheTilingDs::SetupCacheLayout(const gert::TilingContext* const context)
305	{
306	    // Setup Default Contiguous Stride
307	    // A standard contiguous block stride = BlockSize * NumHead * HeadDim
308	    int64_t numHead = tilingData_.get_numHead();
309	    auto v_shape_ptr = context_->GetInputShape(V_CACHE_INDEX);
310	    int64_t defaultVStride = blockSize_ * numHead * dv_;
311	    if (v_shape_ptr != nullptr) {
312	        defaultVStride = blockSize_ * numHead * v_shape_ptr->GetOriginShape().GetDim(SHAPE_IDX_D);
313	    }
314	    int64_t defaultKStride = blockSize_ * numHead * dk_;
315	
316	    int64_t vStride_ = defaultVStride;
317	    int64_t kStride_ = 0;
318	    int64_t cacheLayOut = static_cast<int64_t>(CacheLayout::CONTIGUOUS);
319	
320	    // Overwrite Stride and Determine Layout if in PA Mode
321	    if (isPagedAttention_ && methodMode_ == 0) {
322	        // Fetch the actual physical stride pointer from the framework
323	        const gert::Stride* v_stride_ptr = context_->GetInputStride(V_CACHE_INDEX);
324	
325	        // Check if the pointer is valid and has at least 1 dimension
326	        if (v_stride_ptr != nullptr && v_stride_ptr->GetDimNum() > 0) {
327	            vStride_ = v_stride_ptr->GetStride(0); // Dim 0 stride is the jump between blocks
328	        }
329	
330	        OP_CHECK_IF(
331	            vStride_ < defaultVStride, OP_LOGE(context_, "vStride_ is less than defaultVStride"),
332	            return ge::GRAPH_FAILED);
333	
334	        // 2. Check if K cache (ckv_cache) was actually provided
335	        auto k_shape_ptr = context_->GetInputShape(K_CACHE_INDEX);
336	        if (k_shape_ptr == nullptr || k_shape_ptr->GetOriginShape().GetDimNum() == 1) {
337	            // ----------------------------------------
338	            // K_CACHE is EMPTY -> SFA Mode (Fused K & V)
339	            // ----------------------------------------
340	            // Check the quantMode (assuming 0 is non-quantized, adjust if your enum differs)
341	            if (inputQuantMode_ == QuantClass::NONE) {
342	                cacheLayOut = static_cast<int64_t>(CacheLayout::SFA_NO_QUANT);
343	            }
344	
345	            if (inputQuantMode_ == QuantClass::PERTILE_128) {
346	                tilingData_.set_pertileSize(C8_QUANT_PER_TILE_ELENUM);
347	                cacheLayOut = static_cast<int64_t>(CacheLayout::SFA_C8);
348	            }
349	        } else {
350	            // ----------------------------------------
351	            // K_CACHE is PROVIDED -> SWA Mode (Separate K & V)
352	            // ----------------------------------------
353	            const gert::Stride* k_stride_ptr = context_->GetInputStride(K_CACHE_INDEX);
354	            if (k_stride_ptr != nullptr && k_stride_ptr->GetDimNum() > 0) {
355	                kStride_ = k_stride_ptr->GetStride(0);
356	            } else {
357	                kStride_ = defaultKStride;
358	            }
359	
360	            OP_CHECK_IF(
361	                kStride_ < defaultKStride, OP_LOGE(context_, "kStride_ is less than defaultKStride"),
362	                return ge::GRAPH_FAILED);
363	
364	            if (vStride_ > defaultVStride || kStride_ > defaultKStride) {
365	                // Check if stride matches the SFA merged cache size (Dk + Dv)
366	                cacheLayOut = static_cast<int64_t>(CacheLayout::SWA);
367	            }
368	        }
369	    }
370	
371	    tilingData_.set_vStride(vStride_);
372	    tilingData_.set_kStride(kStride_);
373	    tilingData_.set_cacheLayOut(cacheLayOut);
374	    return ge::GRAPH_SUCCESS;
375	}
376	
377	void AiInfraKvRmsNormRopeCacheTilingDs::DoOpTilingPaBlkNz()
378	{
379	    int64_t batchSize = tilingData_.get_batchSize();
380	    int64_t seqLen = tilingData_.get_seqLength();
381	    int64_t numHead = tilingData_.get_numHead();
382	    int64_t bns = batchSize * numHead * seqLen;
383	    int64_t blockFactor = (bns + coreNum_ - 1) / coreNum_;
384	    int64_t numBlocks = (bns + blockFactor - 1) / blockFactor;
385	    tilingData_.set_blockFactor(blockFactor);
386	    tilingData_.set_numBlocks(numBlocks);
387	
388	    int64_t maxUbFactor = (methodMode_ == 1) ? 32 : 16;
389	    constexpr static int64_t needUbSize = static_cast<int64_t>(170) * static_cast<int64_t>(1024);
390	    if (static_cast<int64_t>(ubSize_) >= static_cast<int64_t>(needUbSize)) {
391	        tilingData_.set_ubFactor(maxUbFactor);
392	    } else {
393	        tilingData_.set_ubFactor(1);
394	    }
395	}
