405	ge::graphStatus AiInfraKvRmsNormRopeCacheTilingDs::DoOpTiling()
406	{
407	    RMS_NORM_LENGTH = RMS_NORM_LENGTHS[methodMode_];
408	    auto kvShapeTuple = GetShapeTuple(context_, KV_INDEX);
409	    tilingData_.set_batchSize(std::get<SHAPE_IDX_B>(kvShapeTuple));
410	    tilingData_.set_numHead(std::get<SHAPE_IDX_N>(kvShapeTuple));
411	    tilingData_.set_seqLength(std::get<SHAPE_IDX_S>(kvShapeTuple));
412	    tilingData_.set_cacheLength(cacheLength_);
413	    tilingData_.set_blockSize(blockSize_);
414	    tilingData_.set_reciprocal(reciprocal_);
415	    tilingData_.set_epsilon(epsilon_);
416	    tilingData_.set_methodMode(methodMode_);
417	
418	    // Setup cache layout (stride, SFA/SWA detection)
419	    auto retLayout = SetupCacheLayout(context_);
420	    if (retLayout != ge::GRAPH_SUCCESS) {
421	        return retLayout;
422	    }
423	
424	    if (isOutputKv_) {
425	        tilingData_.set_isOutputKv(1);
426	    } else {
427	        tilingData_.set_isOutputKv(0);
428	    }
429	
430	    // Validate quant mode and check scale/offset shapes
431	    auto retValidate = ValidateStaticQuantMode(context_);
432	    if (retValidate != ge::GRAPH_SUCCESS) {
433	        return retValidate;
434	    }
435	    OP_CHECK_IF(
436	        (!isRegbase_) && (dk_ != ROPE_LENGTH), OP_LOGE(context_->GetNodeName(), "rope last dim only support 64."),
437	        return ge::GRAPH_FAILED);
438	    OP_CHECK_IF(
439	        (!isRegbase_) && (dv_ != RMS_NORM_LENGTH),
440	        OP_LOGE(context_->GetNodeName(), "rms_norm last dim only support 512 or 192."), return ge::GRAPH_FAILED);
441	    if (methodMode_ == 0) {
442	        OP_CHECK_IF(
443	            (!isRegbase_) && (kv_ != D_LENGTH), OP_LOGE(context_->GetNodeName(), "rms_norm last dim only support 576."),
444	            return ge::GRAPH_FAILED);
445	    } else {
446	        OP_CHECK_IF(
447	            (!isRegbase_) && (vlen_ != V_LENGTH),
448	            OP_LOGE(context_->GetNodeName(), "Tensor v last dim only support 128."), return ge::GRAPH_FAILED);
449	    }
450	
451	    if (currentCacheMode_ == CacheMode::PA && inputQuantMode_ != QuantClass::NONE) {
452	        DoOpTilingPaBlkNz();
453	        tilingKey_ = TilingKeyAttachQuantStat(TLING_KEY_5001, this->inputQuantMode_); // TLING_KEY_50X1, X>0
454	        return ge::GRAPH_SUCCESS;
455	    }
456	
457	    // Expansion Quantmodes and Cache Layouts are ONLY available for PA cache for now, therefore other cache modes do
458	    // not need to adopt 'TilingKeyAttachQuantStat'.
459	    if (currentCacheMode_ == CacheMode::PA_BLK_BNSD) {
460	        DoOpTilingPaBlkNz();
461	        if (quantMode_ != NON_QUANT_MODE) {
462	            tilingKey_ = TLING_KEY_5010;
463	        } else {
464	            tilingKey_ = TLING_KEY_5000;
465	        }
466	        return ge::GRAPH_SUCCESS;
467	    }
468	
469	    if (currentCacheMode_ == CacheMode::PA_NZ) {
470	        DoOpTilingPaBlkNz();
471	        if (quantMode_ != NON_QUANT_MODE) {
472	            tilingKey_ = TLING_KEY_4011;
473	        } else {
474	            tilingKey_ = TLING_KEY_4001;
475	        }
476	        return ge::GRAPH_SUCCESS;
477	    }
478	
479	    if (currentCacheMode_ == CacheMode::PA_BLK_NZ) {
480	        DoOpTilingPaBlkNz();
481	        if (quantMode_ != NON_QUANT_MODE) {
482	            tilingKey_ = TLING_KEY_4010;
483	        } else {
484	            tilingKey_ = TLING_KEY_4000;
485	        }
486	        return ge::GRAPH_SUCCESS;
487	    }
488	
489	    int8_t outputKvValue = tilingData_.get_isOutputKv();
490	    bool outputKv = outputKvValue == 0 ? false : true;
491	    if (outputKv && currentCacheMode_ == CacheMode::PA) {
492	        DoOpTilingPaBlkNz();
493	        tilingKey_ = TLING_KEY_5001;
494	        return ge::GRAPH_SUCCESS;
495	    }
496	
497	    int64_t batchSize = tilingData_.get_batchSize();
498	    int64_t seqLen = tilingData_.get_seqLength(); // Skv
499	    int64_t numHead = tilingData_.get_numHead();
500	
501	    // Decide exact tiling strategy and computation template applied to current input
502	    this->isB1SD_ = this->IsB1SD(context_);
503	    // Choose template with the largest throughput, token * head per core, as the tiling strategy.
504	    this->isCutT_ =
505	        this->isB1SD_; // When '&& seqLen>1' is removed, deafult tiling strategy for Skv=Srope=1 is set to CutT.
506	
507	    if (!this->isCutT_) {
508	        // This is a temporary lazy design to accommodate MTP tiling defect that DOES NOT support tailcore.
509	        // Redirect to CutT.
510	        this->isCutT_ = (BATCHES_FOR_EACH_CORE * coreNum_ < batchSize);
511	    }
512	
513	    // Final tiling decision
514	    if (isCutT_) {
515	        // B, S axes of kv and rope terms are aligned, therefore 'CutBS' can be reduced to 'CutT', whose procession
516	        // collapses from B-S loops into token traversal.
517	        int64_t bns = batchSize * numHead * seqLen;                // total token-head to process
518	        int64_t blockFactor = (bns + coreNum_ - 1) / coreNum_;     // token-head per core
519	        int64_t numBlocks = (bns + blockFactor - 1) / blockFactor; // tailcore index
520	
521	        tilingData_.set_blockFactor(blockFactor);
522	        tilingData_.set_numBlocks(numBlocks);
523	
524	        int64_t maxUbFactor = (methodMode_ == 1) ? 32 : 16;
525	        constexpr static int64_t needUbSize = static_cast<int64_t>(170) * static_cast<int64_t>(1024);
526	        if (static_cast<int64_t>(ubSize_) >= static_cast<int64_t>(needUbSize)) {
527	            tilingData_.set_ubFactor(maxUbFactor);
528	        } else {
529	            tilingData_.set_ubFactor(1);
530	        }
531	    } else {
532	        // Switch to CutB tiling when S_rope = 1, predict parallel tokens in multiple batches.
533	        if (batchSize % BATCHES_FOR_EACH_CORE == 0) {
534	            tilingData_.set_numBlocks(batchSize / BATCHES_FOR_EACH_CORE);
535	            tilingData_.set_rowsPerBlock(BATCHES_FOR_EACH_CORE);
536	        } else {
537	            tilingData_.set_numBlocks(batchSize);
538	            tilingData_.set_rowsPerBlock(1);
539	        }
540	        // Check numBlocks <= MAX_BLOCK_DIM
541	        OP_CHECK_IF(
542	            tilingData_.get_numBlocks() > MAX_BLOCK_DIM,
543	            OP_LOGE(context_->GetNodeName(), "numBlocks must be smaller than 65535."), return ge::GRAPH_FAILED);
544	    }
545	
546	    // Redirect quant mode to tilingkey
547	
548	    // Check Point: QuantClass shall be matched with sub quantmodes.
549	    OP_LOGD(
550	        context_->GetNodeName(),
551	        "TilingKey Decision Start: isPagedAttention_ = %d, inputQuantMode_ = %lld, StaticQuantModes[KV, K, V]=[%lld, "
552	        "%lld, %lld].\n",
553	        isPagedAttention_ ? 1 : 0, static_cast<int64_t>(inputQuantMode_), this->quantMode_, this->kStaticQuantMode,
554	        this->vStaticQuantMode);
555	
556	    if (!isPagedAttention_ && inputQuantMode_ == QuantClass::NONE) {
557	        // isOutputKv is viable once output layout is different from the input or quant mode enabled.
558	        tilingData_.set_isOutputKv(0);
559	    }
560	
561	    if (methodMode_ == DIM_ONE) {
562	        if (this->isCutT_) {
563	            if (isPagedAttention_) {
564	                tilingKey_ = TLING_KEY_3001;
565	            } else { // !isPagedAttention_
566	                if (quantMode_ > NON_QUANT_MODE) {
567	                    tilingKey_ = TLING_KEY_3010;
568	                } else {
569	                    // Redirect Expansion quantmodes not supported to NoneQuant
570	                    tilingKey_ = TLING_KEY_3000;
571	                }
572	            }
573	        } else {
574	            if (isPagedAttention_) {
575	                tilingKey_ = TLING_KEY_2000;
576	            } else { // !isPagedAttention_
577	                // STP is not adopted to expansion quant modes or cache layouts.
578	                if (quantMode_ > NON_QUANT_MODE) {
579	                    tilingKey_ = TLING_KEY_1010;
580	                } else {
581	                    // Redirect Expansion quantmodes not supported to NoneQuant
582	                    tilingKey_ = TLING_KEY_1000;
583	                }
584	            }
585	        }
586	    } else {
587	        // Quant modes are not available in V1
588	        if (this->isCutT_) {
589	            if (isPagedAttention_) {
590	                tilingKey_ = TLING_KEY_3001;
591	            } else {
592	                tilingKey_ = TLING_KEY_3000;
593	            }
594	        } else {
595	            if (isPagedAttention_) {
596	                tilingKey_ = TLING_KEY_2000;
597	            } else {
598	                tilingKey_ = TLING_KEY_1000;
599	            }
600	        }
601	    }
602	
603	    if (!this->isCutT_ && isMTP_) {
604	        // Shared rope terms among multiple batches and seqLen>1, Multiple Token Prediction is available.
605	        tilingKey_ += 1;
606	    }
607	    return ge::GRAPH_SUCCESS;
608	}
609	
610	ge::graphStatus AiInfraKvRmsNormRopeCacheTilingDs::PostTiling()
611	{
612	    context_->SetTilingKey(GetTilingKey());
613	    context_->SetBlockDim(tilingData_.get_numBlocks());
614	    size_t* workspaces = context_->GetWorkspaceSizes(1);
615	    OP_CHECK_IF(workspaces == nullptr,
616	        OP_LOGE(context_->GetNodeName(), "GetWorkspaceSizes is nullptr"),
617	        return ge::GRAPH_FAILED);
618	    workspaces[0] = DEFAULT_WORKSPACE_SIZE;
619	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
620	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
621	    return ge::GRAPH_SUCCESS;
622	}
623	
624	ge::graphStatus AiInfraKvRmsNormRopeCacheTilingDs::GetShapeAttrsInfo()
625	{
626	    auto ret = AiInfraKvRmsNormRopeCacheTilingBase::GetShapeAttrsInfo();
627	    if (ret != ge::GRAPH_SUCCESS) {
628	        return ret;
629	    }
630	
631	    auto retRotary = SetupRotaryMode(context_);
632	    if (retRotary != ge::GRAPH_SUCCESS) {
633	        return retRotary;
634	    }
635	
636	    auto retQuant = SetupQuantClass(context_);
637	    if (retQuant != ge::GRAPH_SUCCESS) {
638	        return retQuant;
639	    }
640	
641	    return ge::GRAPH_SUCCESS;
642	}
643	
644	REGISTER_OPS_TILING_TEMPLATE(AiInfraKvRmsNormRopeCache, AiInfraKvRmsNormRopeCacheTilingDs, TEMPLATE_DS_PRIORITY);
645	} // namespace optiling

