170	ge::graphStatus AiInfraKvRmsNormRopeCacheRegbaseFullLoadTiling::DoOpTiling()
171	{
172	    auto kvShapeTuple = GetShapeTuple(context_, KV_INDEX);
173	    int64_t batchSize = std::get<SHAPE_IDX_B>(kvShapeTuple);
174	    int64_t seqLen = std::get<SHAPE_IDX_S>(kvShapeTuple);
175	    int64_t numHead = std::get<SHAPE_IDX_N>(kvShapeTuple);
176	    auto scale1Shape = context_->GetOptionalInputShape(K_ROPE_SCALE_IDX);
177	    auto scale2Shape = context_->GetOptionalInputShape(C_KV_SCALE_IDX);
178	    auto offset1Shape = context_->GetOptionalInputShape(K_ROPE_OFFSET_IDX);
179	    auto offset2Shape = context_->GetOptionalInputShape(C_KV_OFFSET_IDX);
180	
181	    OP_CHECK_IF(
182	        CheckInputShapeIsEmpty() != ge::GRAPH_SUCCESS,
183	        OP_LOGE(context_->GetNodeName(), "The input param can not be empty"), return ge::GRAPH_FAILED);
184	    if (quantMode_ == QUANT_MODE) {
185	        OP_CHECK_IF(
186	            !CheckScaleOffsetShape(scale1Shape, dk_, kScaleType_),
187	            OP_LOGE(context_->GetNodeName(), "k_rope_scale shape invalid."), return ge::GRAPH_FAILED);
188	        OP_CHECK_IF(
189	            !CheckScaleOffsetShape(scale2Shape, dv_, vScaleType_),
190	            OP_LOGE(context_->GetNodeName(), "c_kv_scale shape invalid."), return ge::GRAPH_FAILED);
191	        OP_CHECK_IF(
192	            !CheckScaleOffsetShape(offset1Shape, dk_, kOffsetType_),
193	            OP_LOGE(context_->GetNodeName(), "k_rope_offset shape invalid."), return ge::GRAPH_FAILED);
194	        OP_CHECK_IF(
195	            !CheckScaleOffsetShape(offset2Shape, dv_, vOffsetType_),
196	            OP_LOGE(context_->GetNodeName(), "c_kv_offset shape invalid."), return ge::GRAPH_FAILED);
197	    }
198	    CacheLayout cacheLayOut = CacheLayout::CONTIGUOUS;
199	    // get v_cache and k_cache stride
200	    int64_t defaultVStride = blockSize_ * numHead * dv_;
201	    int64_t defaultKStride = blockSize_ * numHead * dk_;
202	
203	    int64_t vStride_ = defaultVStride;
204	    int64_t kStride_ = 0;
205	
206	    auto attrs = context_->GetAttrs();
207	    OP_CHECK_NULL_WITH_CONTEXT(context_, attrs);
208	
209	    const char* tmpRotaryMode = attrs->GetStr(ROTARY_MODE_IDX);
210	    if (tmpRotaryMode != nullptr) {
211	        std::string rotaryMode = tmpRotaryMode;
212	        std::unordered_map<std::string, RotaryMode> rotaryModeMap = {
213	            {"interleave-half", RotaryMode::INTER_HALF}, {"half", RotaryMode::HALF}};
214	        auto getRotaryMode = [&rotaryModeMap](const std::string& mode) -> RotaryMode {
215	            auto it = rotaryModeMap.find(mode);
216	            return (it != rotaryModeMap.end()) ? it->second : RotaryMode::INTER_HALF;
217	        };
218	        rotaryMode_ = getRotaryMode(rotaryMode);
219	    } else {
220	        rotaryMode_ = RotaryMode::INTER_HALF;
221	    }
222	
223	    const char* tmpInputQuantMode = attrs->GetStr(INPUT_QUANT_MODE_IDX);
224	    if (tmpInputQuantMode != nullptr) {
225	        std::string inputQuantMode = tmpInputQuantMode;
226	        std::unordered_map<std::string, QuantClass> inputQuantModeMap = {
227	            {"none", QuantClass::NONE}, {"static", QuantClass::STATIC}, {"pertile128", QuantClass::PERTILE_128}};
228	        auto getInputQuantMode = [&inputQuantModeMap](const std::string& mode) -> QuantClass {
229	            auto it = inputQuantModeMap.find(mode);
230	            return (it != inputQuantModeMap.end()) ? it->second : QuantClass::STATIC;
231	        };
232	        inputQuantMode_ = getInputQuantMode(inputQuantMode);
233	    } else {
234	        inputQuantMode_ = QuantClass::NONE;
235	    }
236	
237	    const gert::Stride* vStridePtr = context_->GetInputStride(V_CACHE_INDEX);
238	    if (vStridePtr != nullptr && vStridePtr->GetDimNum() > 0) {
239	        vStride_ = vStridePtr->GetStride(0);
240	    }
241	
242	    OP_CHECK_IF(
243	        vStride_ < defaultVStride, OP_LOGE(context_->GetNodeName(), "vStride_ is less than defaultVStride"),
244	        return ge::GRAPH_FAILED);
245	    int64_t pertileSize = 0; // tilesize in Dynamic quant
246	    int64_t dynamicScaleAlign = 0;
247	
248	    auto kShapePtr = context_->GetInputShape(K_CACHE_INDEX);
249	    if (kShapePtr == nullptr || kShapePtr->GetOriginShape().GetDimNum() == 1) {
250	        if (quantMode_ == NON_QUANT_MODE) {
251	            if (inputQuantMode_ == QuantClass::NONE || inputQuantMode_ == QuantClass::STATIC) {
252	                cacheLayOut = CacheLayout::SFA_NO_QUANT;
253	            } else if (inputQuantMode_ == QuantClass::PERTILE_128) {
254	                cacheLayOut = CacheLayout::SFA_C8;
255	                pertileSize = TILE_128_VALUE;
256	                OP_CHECK_IF(
257	                    dv_ % pertileSize != 0,
258	                    OP_LOGE(context_->GetNodeName(), "dv must be a multiple of %lld", pertileSize),
259	                    return ge::GRAPH_FAILED);
260	                dynamicScaleAlign = CeilAlign(dv_ / pertileSize, static_cast<int64_t>(ubBlockSize_ / sizeof(float)));
261	            } else {
262	                OP_LOGE(context_->GetNodeName(), "quant mode not support static when k_cache is none or 1");
263	                return ge::GRAPH_FAILED;
264	            }
265	        } else {
266	            OP_LOGE(context_->GetNodeName(), "k_scale or v_scale should be none when k_cache is none or 1");
267	            return ge::GRAPH_FAILED;
268	        }
269	    } else {
270	        const gert::Stride* kStridePtr = context_->GetInputStride(K_CACHE_INDEX);
271	        if (kStridePtr != nullptr && kStridePtr->GetDimNum() > 0) {
272	            kStride_ = kStridePtr->GetStride(0);
273	        } else {
274	            kStride_ = defaultKStride;
275	        }
276	
277	        OP_CHECK_IF(
278	            kStride_ < defaultKStride, OP_LOGE(context_->GetNodeName(), "kStride_ is less than defaultKStride"),
279	            return ge::GRAPH_FAILED);
280	
281	        if (vStride_ > defaultVStride || kStride_ > defaultKStride) {
282	            cacheLayOut = CacheLayout::SWA;
283	        }
284	    }
285	
286	    OP_CHECK_IF(
287	        (dk_ % CONST_TWO) != 0, OP_LOGE(context_->GetNodeName(), "headsize of cos is invalid."),
288	        return ge::GRAPH_FAILED);
289	
290	    OP_CHECK_IF(numHead != 1, OP_LOGE(context_->GetNodeName(), "N must be one"), return ge::GRAPH_FAILED);
291	
292	    OP_CHECK_IF(
293	        !CheckInputDtype(), OP_LOGE(context_->GetNodeName(), "kvrmsnormrope dtype is invalid."),
294	        return ge::GRAPH_FAILED);
295	
296	    // N = 1
297	    int64_t bs = batchSize * seqLen * numHead;
298	    tilingData_.set_batchSize(batchSize);
299	    tilingData_.set_numHead(numHead);
300	    tilingData_.set_seqLength(seqLen);
301	    tilingData_.set_cacheLength(cacheLength_);
302	    tilingData_.set_dk(dk_);
303	    tilingData_.set_halfDk(dk_ / CONST_TWO);
304	
305	    int64_t dkAlign = CeilAlign(dk_, static_cast<int64_t>(ubBlockSize_ / kvDtypeSize_));
306	    int64_t dkB8Align = CeilAlign(dk_, static_cast<int64_t>(ubBlockSize_ / sizeof(int8_t)));
307	    int64_t halfDkAlign = CeilAlign(tilingData_.get_halfDk(), (ubBlockSize_ / kvDtypeSize_));
308	
309	    tilingData_.set_dkAlign(dkAlign);
310	    tilingData_.set_dkB8Align(dkB8Align);
311	    tilingData_.set_halfDkAlign(halfDkAlign);
312	    tilingData_.set_dv(dv_);
313	
314	    int64_t dvAlign = CeilAlign(dv_, static_cast<int64_t>(ubBlockSize_ / kvDtypeSize_));
315	    tilingData_.set_dvAlign(dvAlign);
316	
317	    int64_t dvB8Align = CeilAlign(dvAlign, static_cast<int64_t>(ubBlockSize_ / sizeof(int8_t)));
318	
319	    tilingData_.set_dvB8Align(dvB8Align);
320	    tilingData_.set_blockSize(blockSize_);
321	    tilingData_.set_reciprocal(reciprocal_);
322	    tilingData_.set_epsilon(epsilon_);
323	    tilingData_.set_cosSinNeedBrc(cosSinNeedBrc_);
324	    tilingData_.set_kScaleType(kScaleType_);
325	    tilingData_.set_kOffsetType(kOffsetType_);
326	    tilingData_.set_vScaleType(vScaleType_);
327	    tilingData_.set_vOffsetType(vOffsetType_);
328	    tilingData_.set_cacheMode(static_cast<int64_t>(currentCacheMode_));
329	    tilingData_.set_kQuantMode(this->kStaticQuantMode);
330	    if (inputQuantMode_ == QuantClass::PERTILE_128) {
331	        tilingData_.set_vQuantMode(V_PERTILE_128_QUANT_MODE);
332	    } else {
333	        tilingData_.set_vQuantMode(this->vStaticQuantMode);
334	    }
335	    tilingData_.set_rotaryMode(static_cast<int64_t>(rotaryMode_));
336	    tilingData_.set_cacheLayOut(static_cast<int64_t>(cacheLayOut));
337	    tilingData_.set_vStride(vStride_);
338	    tilingData_.set_kStride(kStride_);
339	    tilingData_.set_pertileSize(pertileSize);
340	    tilingData_.set_dynamicScaleAlign(dynamicScaleAlign);
341	
342	    int64_t kScaleOffsetUbSize = kScaleType_ > 0 ? K_SCALE_OFFSET_UB_NUM * halfDkAlign * sizeof(float) : 0;
343	    int64_t vScaleOffsetUbSize = vScaleType_ > 0 ? V_SCALE_OFFSET_UB_NUM * dvAlign * sizeof(float) : 0;
344	    int64_t gammaUbSize = dvAlign * kvDtypeSize_;
345	    int64_t inCosSinUbSize = COS_SIN_UB_NUM * halfDkAlign * kvDtypeSize_;
346	    int64_t inUbSize = std::max(dkAlign, dvAlign) * kvDtypeSize_;
347	    int64_t kOutUbsize = 0;
348	    int64_t vOutUbsize = 0;
349	    // k量化场景
350	    if (kScaleType_ > 0) {
351	        if (isOutputKv_) {
352	            kOutUbsize = dkB8Align * kvDtypeSize_ + dkB8Align * sizeof(int8_t);
353	        } else {
354	            kOutUbsize = dkB8Align * sizeof(int8_t);
355	        }
356	    } else {
357	        kOutUbsize = dkAlign * kvDtypeSize_;
358	    }
359	    // v量化场景
360	    if (vScaleType_ > 0) {
361	        if (isOutputKv_) {
362	            vOutUbsize = dvB8Align * kvDtypeSize_ + dvB8Align * sizeof(int8_t);
363	        } else {
364	            vOutUbsize = dvB8Align * kvDtypeSize_ + dvB8Align * sizeof(int8_t);
365	        }
366	    } else if (quantMode_ != QUANT_MODE && inputQuantMode_ == QuantClass::PERTILE_128) {
367	        vOutUbsize = dvB8Align * kvDtypeSize_ + dvB8Align * sizeof(int8_t);
368	        vOutUbsize += dynamicScaleAlign * sizeof(float);
369	    } else {
370	        vOutUbsize = dvAlign * kvDtypeSize_;
371	    }
372	    int64_t outUbSize = std::max(kOutUbsize, vOutUbsize);
373	    int64_t ropeWspSize = 2 * vlFp32_ * sizeof(float);
374	    int64_t rmsNormWspSize = dvAlign * sizeof(float);
375	
376	    int64_t ubFactor =
377	        (static_cast<int64_t>(ubSize_) - UB_RESERVED_BYTE - kScaleOffsetUbSize - vScaleOffsetUbSize - gammaUbSize -
378	         ropeWspSize) /
379	        (DOUBLE_BUFFER * inUbSize + DOUBLE_BUFFER * inCosSinUbSize + DOUBLE_BUFFER * outUbSize + rmsNormWspSize);
380	
381	    OP_CHECK_IF(
382	        (ubFactor <= 0),
383	        OP_LOGI(context_->GetNodeName(), "D full load template is not capable. dv is %ld, dk is %ld", dv_, dk_),
384	        return ge::GRAPH_PARAM_INVALID);
385	    tilingData_.set_inUbSize(inUbSize);
386	    tilingData_.set_outUbSize(outUbSize);
387	    tilingData_.set_rmsNormWspSize(rmsNormWspSize);
388	
389	    int64_t blockFactor = (bs + coreNum_ - 1) / coreNum_;
390	    ubFactor = ubFactor < blockFactor ? ubFactor : blockFactor;
391	    usedCoreNum_ = (bs + blockFactor - 1) / blockFactor;
392	    tilingData_.set_blockFactor(blockFactor);
393	    tilingData_.set_ubFactor(ubFactor);
394	    int64_t outputKvKey = isOutputKv_ == true ? 1 : 0;
395	    tilingData_.set_isOutputKv(outputKvKey);
396	    tilingKey_ = FULL_LOAD_BASE_TILING_KEY;
397	    return ge::GRAPH_SUCCESS;
398	}
399	
400	ge::graphStatus AiInfraKvRmsNormRopeCacheRegbaseFullLoadTiling::PostTiling()
401	{
402	    context_->SetTilingKey(GetTilingKey());
403	    context_->SetBlockDim(usedCoreNum_);
404	    size_t* workspaces = context_->GetWorkspaceSizes(1);
405	    OP_CHECK_IF(
406	        workspaces == nullptr, OP_LOGE(context_->GetNodeName(), "GetWorkspaceSizes is nullptr"),
407	        return ge::GRAPH_FAILED);
408	    workspaces[0] = DEFAULT_WORKSPACE_SIZE;
409	    tilingData_.SaveToBuffer(context_->GetRawTilingData()->GetData(), context_->GetRawTilingData()->GetCapacity());
410	    context_->GetRawTilingData()->SetDataSize(tilingData_.GetDataSize());
411	    return ge::GRAPH_SUCCESS;
412	}
413	
414	REGISTER_OPS_TILING_TEMPLATE(
415	    AiInfraKvRmsNormRopeCache, AiInfraKvRmsNormRopeCacheRegbaseFullLoadTiling, TEMPLATE_D_FULL_LOAD_PRIORITY);
416	} // namespace optiling
