137	    template <int64_t rpMode, int64_t clLayout, int64_t isSFACountiguous>
138	    __aicore__ inline void ProcessV1Impl()
139	    {
140	        DataCopyPadExtParams<KV_DTYPE> padParams{false, 0, 0, 0};
141	        DataCopyPadExtParams<int64_t> padParamsInt64{false, 0, 0, 0};
142	        DataCopyExtParams copyParamsContinguous;
143	        copyParamsContinguous.blockCount = 1;
144	        // CopyIn gamma: [this->RMS_NORM_LENGTH]
145	        LocalTensor<float> gammaLocalFp32 = this->inQueueGamma.template AllocTensor<float>();
146	        LocalTensor<KV_DTYPE> gammaLocal = gammaLocalFp32.template ReinterpretCast<KV_DTYPE>()[this->RMS_NORM_LENGTH];
147	        copyParamsContinguous.blockLen = this->RMS_NORM_LENGTH * sizeof(KV_DTYPE);
148	        DataCopyPad(gammaLocal, this->gammaGm, copyParamsContinguous, padParams);
149	        this->inQueueGamma.EnQue(gammaLocalFp32);
150	        gammaLocalFp32 = this->inQueueGamma.template DeQue<float>();
151	        gammaLocal = gammaLocalFp32.template ReinterpretCast<KV_DTYPE>()[this->RMS_NORM_LENGTH];
152	        Cast(gammaLocalFp32, gammaLocal, RoundMode::CAST_NONE, this->RMS_NORM_LENGTH);
153	
154	        LocalTensor<float> workspaceBuffer = this->wsBuffer.template Get<float>();
155	        for (int64_t loopIdx = 0; loopIdx < this->ubLoop; ++loopIdx) {
156	            int64_t kvGlobalMemoryOffset = loopIdx * this->ubFactor * (this->RMS_NORM_LENGTH + this->ROPE_LENGTH);
157	            int64_t freqGlobalMemoryOffset = loopIdx * this->ubFactor * this->ROPE_LENGTH;
158	            int64_t indexGlobalMemoryOffset = loopIdx * this->ubFactor;
159	            int64_t startIdx = GetBlockIdx() * this->tilingData_->blockFactor + loopIdx * this->ubFactor;
160	
161	            LocalTensor<KV_DTYPE> ropeLocal = this->inQueueX.template AllocTensor<KV_DTYPE>();
162	            LocalTensor<KV_DTYPE> cosLocal = ropeLocal[this->ubFactor * this->ROPE_LENGTH];
163	            LocalTensor<KV_DTYPE> sinLocal = cosLocal[this->ubFactor * this->ROPE_LENGTH];
164	            // CopyIn x/cos/sin [this->ubFactor, this->ROPE_LENGTH]
165	            DataCopyExtParams copyParams{
166	                static_cast<uint16_t>(this->ubFactor), static_cast<uint32_t>(this->ROPE_LENGTH * sizeof(KV_DTYPE)),
167	                static_cast<uint32_t>(this->RMS_NORM_LENGTH * sizeof(KV_DTYPE)), 0, 0};
168	            DataCopyPad(ropeLocal, this->kvGm[kvGlobalMemoryOffset + this->RMS_NORM_LENGTH], copyParams, padParams);
169	            copyParamsContinguous.blockLen = this->ubFactor * this->ROPE_LENGTH * sizeof(KV_DTYPE);
170	            DataCopyPad(cosLocal, this->cosGm[freqGlobalMemoryOffset], copyParamsContinguous, padParams);
171	            DataCopyPad(sinLocal, this->sinGm[freqGlobalMemoryOffset], copyParamsContinguous, padParams);
172	            this->inQueueX.EnQue(ropeLocal);
173	            ropeLocal = this->inQueueX.template DeQue<KV_DTYPE>();
174	            cosLocal = ropeLocal[this->ubFactor * this->ROPE_LENGTH];
175	            sinLocal = cosLocal[this->ubFactor * this->ROPE_LENGTH];
176	
177	            // Calc: RoPE
178	            LocalTensor<KV_DTYPE> outLocal = this->outQueue.template AllocTensor<KV_DTYPE>();
179	            RoPE<KV_DTYPE, true, rpMode>(
180	                outLocal, ropeLocal, cosLocal, sinLocal, workspaceBuffer, this->ubFactor, this->ROPE_LENGTH);
181	            this->inQueueX.FreeTensor(ropeLocal);
182	            this->outQueue.EnQue(outLocal);
183	            outLocal = this->outQueue.template DeQue<KV_DTYPE>();
184	
185	            // Scatter Update kCache (or merged into vCache when cacheLayOut == SFA_NO_QUANT)
186	            DoScatterV1<KV_DTYPE, D1_SIZE4_PA, D0_SIZE16_PA, clLayout, isSFACountiguous>(
187	                this->kCacheGm, this->kCacheGmNd, outLocal, startIdx, this->ubFactor, this->ROPE_LENGTH, true, kStride);
188	
189	            this->outQueue.FreeTensor(outLocal);
190	
191	            // CopyIn x: [this->ubFactor, RmsLength]
192	            LocalTensor<KV_DTYPE> xLocal = this->inQueueX.template AllocTensor<KV_DTYPE>();
193	            copyParams.blockCount = static_cast<uint16_t>(this->ubFactor);
194	            copyParams.blockLen = this->RMS_NORM_LENGTH * sizeof(KV_DTYPE);
195	            copyParams.srcStride = this->ROPE_LENGTH * sizeof(KV_DTYPE);
196	            copyParams.dstStride = 0;
197	            DataCopyPad(xLocal, this->kvGm[kvGlobalMemoryOffset], copyParams, padParams);
198	            this->inQueueX.EnQue(xLocal);
199	            xLocal = this->inQueueX.template DeQue<KV_DTYPE>();
200	
201	            // Calc: RmsNorm
202	            outLocal = this->outQueue.template AllocTensor<KV_DTYPE>();
203	            RmsNorm<KV_DTYPE>(outLocal, xLocal, gammaLocalFp32, workspaceBuffer, this->ubFactor, this->RMS_NORM_LENGTH);
204	            this->inQueueX.FreeTensor(xLocal);
205	            this->outQueue.EnQue(outLocal);
206	            outLocal = this->outQueue.template DeQue<KV_DTYPE>();
207	
208	            // Scatter Update vCache (or merged into vCache first part when cacheLayOut == SFA_NO_QUANT)
209	            DoScatterV1<KV_DTYPE, D1_SIZE32_PA, D0_SIZE16_PA, clLayout, isSFACountiguous>(
210	                this->vCacheGm, this->vCacheGmNd, outLocal, startIdx, this->ubFactor, this->RMS_NORM_LENGTH, false,
211	                vStride);
212	            this->outQueue.FreeTensor(outLocal);
213	        }
214	        if (this->ubTail > 0) {
215	            int64_t kvGlobalMemoryOffset = this->ubLoop * this->ubFactor * (this->RMS_NORM_LENGTH + this->ROPE_LENGTH);
216	            int64_t freqGlobalMemoryOffset = this->ubLoop * this->ubFactor * this->ROPE_LENGTH;
217	            int64_t indexGlobalMemoryOffset = this->ubLoop * this->ubFactor;
218	            int64_t startIdx = GetBlockIdx() * this->tilingData_->blockFactor + this->ubLoop * this->ubFactor;
219	
220	            LocalTensor<KV_DTYPE> ropeLocal = this->inQueueX.template AllocTensor<KV_DTYPE>();
221	            LocalTensor<KV_DTYPE> cosLocal = ropeLocal[this->ubTail * this->ROPE_LENGTH];
222	            LocalTensor<KV_DTYPE> sinLocal = cosLocal[this->ubTail * this->ROPE_LENGTH];
223	            // CopyIn x/cos/sin [this->ubTail, this->ROPE_LENGTH]
224	            DataCopyExtParams copyParams{
225	                static_cast<uint16_t>(this->ubTail), static_cast<uint32_t>(this->ROPE_LENGTH * sizeof(KV_DTYPE)),
226	                static_cast<uint32_t>(this->RMS_NORM_LENGTH * sizeof(KV_DTYPE)), 0, 0};
227	            DataCopyPad(ropeLocal, this->kvGm[kvGlobalMemoryOffset + this->RMS_NORM_LENGTH], copyParams, padParams);
228	            copyParamsContinguous.blockLen = this->ubTail * this->ROPE_LENGTH * sizeof(KV_DTYPE);
229	            DataCopyPad(cosLocal, this->cosGm[freqGlobalMemoryOffset], copyParamsContinguous, padParams);
230	            DataCopyPad(sinLocal, this->sinGm[freqGlobalMemoryOffset], copyParamsContinguous, padParams);
231	            this->inQueueX.EnQue(ropeLocal);
232	            ropeLocal = this->inQueueX.template DeQue<KV_DTYPE>();
233	            cosLocal = ropeLocal[this->ubTail * this->ROPE_LENGTH];
234	            sinLocal = cosLocal[this->ubTail * this->ROPE_LENGTH];
235	
236	            // Calc: RoPE
237	            LocalTensor<KV_DTYPE> outLocal = this->outQueue.template AllocTensor<KV_DTYPE>();
238	            RoPE<KV_DTYPE, true, rpMode>(
239	                outLocal, ropeLocal, cosLocal, sinLocal, workspaceBuffer, this->ubTail, this->ROPE_LENGTH);
240	            this->inQueueX.FreeTensor(ropeLocal);
241	            this->outQueue.EnQue(outLocal);
242	            outLocal = this->outQueue.template DeQue<KV_DTYPE>();
243	
244	            // Scatter Update kCache (or merged into vCache when cacheLayOut == SFA_NO_QUANT)
245	            DoScatterV1<KV_DTYPE, D1_SIZE4_PA, D0_SIZE16_PA, clLayout, isSFACountiguous>(
246	                this->kCacheGm, this->kCacheGmNd, outLocal, startIdx, this->ubTail, this->ROPE_LENGTH, true, kStride);
247	            this->outQueue.FreeTensor(outLocal);
248	
249	            // CopyIn x: [this->ubTail, RmsLength]
250	            LocalTensor<KV_DTYPE> xLocal = this->inQueueX.template AllocTensor<KV_DTYPE>();
251	            copyParams.blockCount = static_cast<uint16_t>(this->ubTail);
252	            copyParams.blockLen = this->RMS_NORM_LENGTH * sizeof(KV_DTYPE);
253	            copyParams.srcStride = this->ROPE_LENGTH * sizeof(KV_DTYPE);
254	            copyParams.dstStride = 0;
255	            DataCopyPad(xLocal, this->kvGm[kvGlobalMemoryOffset], copyParams, padParams);
256	            this->inQueueX.EnQue(xLocal);
257	            xLocal = this->inQueueX.template DeQue<KV_DTYPE>();
