161	        int64_t batchId = 0;
162	        int64_t gmOffset = 0;
163	        for (int64_t i = 0; i < rows; i++) {
164	            int64_t seqIndex = this->indexGm(startIdx + i);
165	            SetFlag<HardEvent::S_MTE3>(eventIDSToMTE3);
166	            WaitFlag<HardEvent::S_MTE3>(eventIDSToMTE3);
167	            if (seqIndex < 0) {
168	                continue;
169	            }
170	
171	            if (tilingData_->cacheMode == NORM_CACHE_MODE) {
172	                batchId = (startIdx + i) / tilingData_->seqLength;
173	                gmOffset = (batchId * tilingData_->cacheLength + seqIndex) * tilingData_->dk;
174	            } else if (tilingData_->cacheMode == PA_CACHE_MODE) {
175	                if (tilingData_->cacheLayOut == CACHE_SWA) {
176	                    int64_t pageIdx = seqIndex / tilingData_->blockSize;
177	                    int64_t tokenInPageIdx = seqIndex % tilingData_->blockSize;
178	                    gmOffset = pageIdx * tilingData_->kStride + tokenInPageIdx * tilingData_->dk;
179	                } else {
180	                    gmOffset = seqIndex * tilingData_->dk;
181	                }
182	            } else if (tilingData_->cacheMode == PA_NZ_CACHE_MODE) {
183	                int64_t pageId = seqIndex / tilingData_->blockSize;
184	                int64_t tokenOffsetInCurrentPage = seqIndex % tilingData_->blockSize;
