192	                DataCopyPad(this->kCacheGm[gmOffset], kQuantLocal[i * tilingData_->dkB8Align], copyOutParams);
193	            } else {
194	                DataCopyPad(this->kCacheGm[gmOffset], kOutLocal[i * tilingData_->dkAlign], copyOutParams);
195	            }
196	        }
