template <typename T_KV, typename T_K_CACHE, typename T_V_CACHE>
class AiInfraKvRmsNormRopeCacheRegbaseFullLoad : public AiInfraKvRmsNormRopeCacheRegbase<T_KV, T_K_CACHE, T_V_CACHE> {
public:
    __aicore__ inline AiInfraKvRmsNormRopeCacheRegbaseFullLoad(
        TPipe* pipe, const AiInfraKvRmsNormRopeCacheRegbaseFullLoadTilingData* tiling)
    {
        tilingData_ = tiling;
        pipe_ = pipe;
    }

    __aicore__ inline void Init(
        GM_ADDR kv, GM_ADDR gamma, GM_ADDR cos, GM_ADDR sin, GM_ADDR index, GM_ADDR k_cache, GM_ADDR v_cache,
        GM_ADDR k_scale, GM_ADDR v_scale, GM_ADDR k_offset, GM_ADDR v_offset, GM_ADDR k_out, GM_ADDR v_out)
    {
