        if (tilingData_->vQuantMode == SYM_QUANT_MODE || tilingData_->vQuantMode == ASYM_QUANT_MODE) {
            pipe_->InitBuffer(
                vScaleOffsetQueue, BUFFER_COUNT_SINGLE,
                V_SCALE_OFFSET_CHANNEL_COUNT * tilingData_->dvAlign * sizeof(float));
        } else if (tilingData_->vQuantMode == V_PERTILE_128_QUANT_MODE) {
            if constexpr (IsSameType<T_V_CACHE, int8_t>::value) {
                this->dynamicQuantFactor = INT8_MAX_SCALE;
            } else if constexpr (IsSameType<T_V_CACHE, hifloat8_t>::value) {
                this->dynamicQuantFactor = HIFLOAT8_MAX_SCALE;
            } else if constexpr (IsSameType<T_V_CACHE, fp8_e4m3fn_t>::value) {
                this->dynamicQuantFactor = FLOAT8_E4M3FN_MAX_SCALE;
            }
        }
    }

    __aicore__ inline void ScatterUpdateK(int64_t rows, int64_t startIdx)
    {
        DataCopyExtParams copyOutParams =
            tilingData_->cacheMode == PA_NZ_CACHE_MODE ? copyOutKParamsNz : copyOutKParams;
        eventIDSToMTE3 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::S_MTE3));
        int64_t batchId = 0;
