                DataCopyPad(this->kCacheGm[gmOffset], kOutLocal[i * tilingData_->dkAlign], copyOutParams);
            }
        }
    }

    __aicore__ inline void ScatterUpdateMergedKCache(int64_t rows, int64_t startIdx)
