549	    template <typename T, bool isElementWise = true, int64_t rpMode = INTERLEAVE_MODE>
550	    __aicore__ inline void RoPE(
551	        const LocalTensor<T>& outLocal, const LocalTensor<T>& xLocal, const LocalTensor<T>& cosLocal,
552	        const LocalTensor<T>& sinLocal, const LocalTensor<float>& wsLocal, int64_t rows, int64_t headSize)
553	    {
554	        if constexpr (isElementWise) {
555	            constexpr static int64_t NUM_FOUR = 4;
556	            constexpr static int64_t NUM_EIGHT = 8;
557	            /**
558	             * cosLocalFp32 : [rows * headSize * 0, rows * headSize * 1]
559	             * sinLocalFp32 : [rows * headSize * 1, rows * headSize * 2]
560	             * y0           : [rows * headSize * 2, rows * headSize * 3]
561	             * y1           : [rows * headSize * 3, rows * headSize * 4]
562	             * realLocalFp32: [rows * headSize * 4, rows * headSize * 5]
563	             * imagLocalFp32: [rows * headSize * 5, rows * headSize * 6]
564	             * realLocal    : [rows * headSize * 6, rows * headSize * 7]
565	             * imagLocal    : [rows * headSize * 7, rows * headSize * 8]
566	             */
567	            int64_t cosLocalFp32Offset = rows * headSize * 0;
568	            int64_t sinLocalFp32Offset = rows * headSize * 1;
569	            int64_t y0Offset = rows * headSize * 2;
570	            int64_t y1Offset = rows * headSize * 3;
571	            int64_t realLocalFp32Offset = rows * headSize * 4;
572	            int64_t imagLocalFp32Offset = rows * headSize * 5;
573	            int64_t realLocalOffset = rows * headSize * 6;
574	            int64_t imagLocalOffset = rows * headSize * 7;
575	
576	            LocalTensor<float> cosLocalFp32 = wsLocal[cosLocalFp32Offset];
577	            LocalTensor<float> sinLocalFp32 = wsLocal[sinLocalFp32Offset];
578	            LocalTensor<float> y0 = wsLocal[y0Offset];
579	            LocalTensor<float> y1 = wsLocal[y1Offset];
580	            LocalTensor<float> realLocalFp32 = wsLocal[realLocalFp32Offset];
581	            LocalTensor<float> imagLocalFp32 = wsLocal[imagLocalFp32Offset];
582	            LocalTensor<T> realLocal = wsLocal[realLocalOffset].template ReinterpretCast<T>();
583	            LocalTensor<T> imagLocal = wsLocal[imagLocalOffset].template ReinterpretCast<T>();
584	
585	            // step #1: cast cosLocal and sinLocal to fp32
586	            Cast(cosLocalFp32, cosLocal, RoundMode::CAST_NONE, rows * headSize);
587	            Cast(sinLocalFp32, sinLocal, RoundMode::CAST_NONE, rows * headSize);
588	            PipeBarrier<PIPE_V>();
589	
590	            // step #2: Extract real and imag
591	            if constexpr (rpMode == INTERLEAVE_MODE) {
592	                constexpr static int64_t NUM_ONE = 1;
593	                constexpr static int64_t NUM_TWO = 2;
594	                // Interleave-half: GatherMask to separate even/odd elements
595	                uint64_t rsvdCnt = 0;
596	                GatherMask(realLocal, xLocal, NUM_ONE, true, rows * headSize, {1, 1, NUM_EIGHT, 0}, rsvdCnt);
597	                GatherMask(imagLocal, xLocal, NUM_TWO, true, rows * headSize, {1, 1, NUM_EIGHT, 0}, rsvdCnt);
598	            } else {
599	                // Half-half: DataCopy to extract first/second half of each token
600	                int64_t halfSize = headSize >> 1;
601	                struct DataCopyParams copyParamsHalf;
602	                copyParamsHalf.blockCount = static_cast<uint16_t>(rows);
603	                copyParamsHalf.blockLen = static_cast<uint16_t>(halfSize * sizeof(T) / BLOCK_SIZE);
604	                copyParamsHalf.srcStride = static_cast<uint16_t>(halfSize * sizeof(T) / BLOCK_SIZE);
605	                copyParamsHalf.dstStride = 0;
606	                DataCopy(realLocal, xLocal, copyParamsHalf);
607	                DataCopy(imagLocal, xLocal[halfSize], copyParamsHalf);
608	            }
609	            PipeBarrier<PIPE_V>();
610	
611	            // step #3: Cast realLocal and imagLocal to Fp32
612	            Cast(realLocalFp32, realLocal, RoundMode::CAST_NONE, rows * (headSize >> 1));
613	            Cast(imagLocalFp32, imagLocal, RoundMode::CAST_NONE, rows * (headSize >> 1));
614	            PipeBarrier<PIPE_V>();
615	
616	            // step #4: y0 = (realLocalFp32, imagLocalFp32) * cosLocalFp32
617	            Mul(y0, realLocalFp32, cosLocalFp32, (headSize >> 1), rows, {1, 1, 1, NUM_EIGHT, NUM_FOUR, NUM_EIGHT});
618	            Mul(y0[(headSize >> 1)], imagLocalFp32, cosLocalFp32[(headSize >> 1)], (headSize >> 1), rows,
619	                {1, 1, 1, NUM_EIGHT, NUM_FOUR, NUM_EIGHT});
620	            PipeBarrier<PIPE_V>();
621	
622	            // step #5: y1 = (-imagLocalFp32, realLocalFp32) * sinLocalFp32
