91	        SingleStepProcess(progress, this->storeSLines, this->storeDataLength, this->storePadDataLength);
92	    }
93	    if (this->ubLast > 0) {
94	        SingleStepProcess(this->ubLoop, this->ubLast, this->ubLastDataLength, this->ubLastPadDataLength);
