99	__aicore__ inline void RotateHalf<T>::RB1sdProcess()
100	{
101	    uint64_t totalSdLength = this->totalSLines * this->dLength;
102	    uint64_t totalNsdLength = totalSdLength * this->bcSecondDim;
103	    for (uint32_t batchLoop = 0; batchLoop < this->bcFirstDim; batchLoop++) {
104	        uint64_t xBatchOffset = batchLoop * totalNsdLength;
105	        uint64_t rBatchOffset = batchLoop * totalSdLength;
106	        for (uint32_t progress = 0; progress < this->ubLoop; progress++) {
107	            RB1sdSingleStepProcess(progress,
108	                this->storeSLines,
109	                xBatchOffset,
110	                rBatchOffset,
111	                this->storeDataLength,
112	                this->storePadDataLength);
113	        }
114	        if (this->ubLast > 0) {
115	            RB1sdSingleStepProcess(this->ubLoop,
116	                this->ubLast,
117	                xBatchOffset,
118	                rBatchOffset,
119	                this->ubLastDataLength,
120	                this->ubLastPadDataLength);
121	        }
