125	template <typename T>
126	__aicore__ inline void RotateHalf<T>::BndProcess()
127	{
128	    CopyInR(0, 1, this->dLength);
129	    LocalTensor<T> cosLocal = inQueueCos.DeQue<T>();
130	    LocalTensor<T> sinLocal = inQueueSin.DeQue<T>();
131	    Muls(sinLocal, sinLocal, (T)(-1.0), this->halfDPadLength);
132	    uint32_t broadcastLines = this->ubLoop > 0 ? this->storeSLines - 1 : this->ubLast - 1;
133	    if (broadcastLines > 0) {
