153	template <typename T>
154	__aicore__ inline void RotateHalf<T>::SingleStepProcess(
155	    uint32_t progress, uint32_t sLines, uint64_t copyLength, uint64_t calcLength)
156	{
157	    uint64_t xOffset, rOffset, bnLoopXStartOffset, progressOffset, batchOffset;
158	    rOffset = progress * this->storeDataLength;
159	    CopyInR(rOffset, sLines, copyLength);
160	    LocalTensor<T> cosLocal = inQueueCos.DeQue<T>();
161	    LocalTensor<T> sinLocal = inQueueSin.DeQue<T>();
162	    this->SinCompute(sinLocal, sLines);
163	
164	    if (this->layout == LAYOUT_BNSD) {
165	        uint64_t totalSdSize = this->totalSLines * this->dLength;
166	        bnLoopXStartOffset = progress * this->storeDataLength;
167	        for (uint32_t bnLoop = 0; bnLoop < this->bnSize; bnLoop++) {
168	            xOffset = bnLoopXStartOffset + bnLoop * totalSdSize;
169	            CopyInX(xOffset, sLines, copyLength);
170	            Compute(cosLocal, sinLocal, sLines, calcLength);
171	            CopyOut(xOffset, sLines, copyLength);
172	        }
173	    } else if (this->layout == LAYOUT_BSND) {
174	        uint64_t totalSndSize = this->totalSLines * this->ndSize;
175	        progressOffset = progress * this->bcSecondDim * this->storeDataLength;
176	        for (uint32_t bLoop = 0; bLoop < this->bcFirstDim; bLoop++) {
177	            batchOffset = bLoop * totalSndSize;
178	            for (uint32_t nLoop = 0; nLoop < this->bcSecondDim; nLoop++) {
179	                xOffset = nLoop * this->dLength + batchOffset + progressOffset;
180	                CopyInX(xOffset, sLines, copyLength);
181	                Compute(cosLocal, sinLocal, sLines, calcLength);
182	                CopyOut(xOffset, sLines, copyLength);
183	            }
184	        }
185	    } else if (this->layout == LAYOUT_SBND) {
186	        bnLoopXStartOffset = progress * this->storeDataLength * this->bnSize;
187	        for (uint32_t bnLoop = 0; bnLoop < this->bnSize; bnLoop++) {
188	            xOffset = bnLoopXStartOffset + bnLoop * this->dLength;
189	            CopyInX(xOffset, sLines, copyLength);
190	            Compute(cosLocal, sinLocal, sLines, calcLength);
191	            CopyOut(xOffset, sLines, copyLength);
192	        }
193	    } else if (this->layout == LAYOUT_NO_BROADCAST) {
194	        CopyInX(rOffset, sLines, copyLength);
195	        Compute(cosLocal, sinLocal, sLines, calcLength);
196	        CopyOut(rOffset, sLines, copyLength);
197	    }
198	    inQueueCos.FreeTensor<T>(cosLocal);
199	    inQueueSin.FreeTensor<T>(sinLocal);
200	}
