203	__aicore__ inline void RotateHalf<T>::RB1sdSingleStepProcess(uint32_t progress, uint32_t sLines,
204	    uint64_t xBatchStartOffset, uint64_t rBatchStartOffset, uint64_t copyLength, uint64_t calcLength)
205	{
206	    CopyInR(progress * this->storeDataLength + rBatchStartOffset, sLines, copyLength);
207	    LocalTensor<T> cosLocal = inQueueCos.DeQue<T>();
208	    LocalTensor<T> sinLocal = inQueueSin.DeQue<T>();
209	    this->SinCompute(sinLocal, sLines);
210	
211	    uint64_t progressXOffset = progress * this->storeDataLength + xBatchStartOffset;
212	    for (uint32_t nLoop = 0; nLoop < this->bcSecondDim; nLoop++) {
213	        uint64_t xOffset = nLoop * this->totalSLines * this->dLength + progressXOffset;
214	        CopyInX(xOffset, sLines, copyLength);
215	        Compute(cosLocal, sinLocal, sLines, calcLength);
216	        CopyOut(xOffset, sLines, copyLength);
217	    }
