222	template <typename T>
223	__aicore__ inline void RotateHalf<T>::CopyInR(uint64_t rStartOffset, uint16_t sLines, uint32_t copyLength)
224	{
225	    LocalTensor<T> cosLocal = inQueueCos.AllocTensor<T>();
226	    LocalTensor<T> sinLocal = inQueueSin.AllocTensor<T>();
227	    if (this->isAligned == true) {
228	        DataCopy(cosLocal, cosGm[rStartOffset], copyLength);
229	        DataCopy(sinLocal, sinGm[rStartOffset], copyLength);
230	    } else {
231	        DataCopyExtParams copyParams{(uint16_t)(2 * sLines),  // blockCount
232	            this->halfDBytes,                                 // blockLen
233	            0,                                                // srcStride(bytes)
234	            0,                                                // dstStride(block)
235	            0};
236	        DataCopyPad(cosLocal, cosGm[rStartOffset], copyParams, this->noPadParams);
237	        DataCopyPad(sinLocal, sinGm[rStartOffset], copyParams, this->noPadParams);
238	    }
239	    inQueueCos.EnQue(cosLocal);
240	    inQueueSin.EnQue(sinLocal);
241	}
