243	template <typename T>
244	__aicore__ inline void RotateHalf<T>::CopyInX(uint64_t xStartOffset, uint16_t sLines, uint32_t copyLength)
245	{
246	    LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
247	    DataCopyExtParams copyParams{};
248	
249	    if (this->isAligned == true) {
250	        if (this->layout == LAYOUT_BNSD || this->layout == LAYOUT_NO_BROADCAST || this->layout == LAYOUT_BND ||
251	            this->layout == LAYOUT_R_B1SD) {
252	            DataCopy(xLocal, xGm[xStartOffset], copyLength);
253	        } else {
254	            copyParams.blockCount = sLines;
255	            copyParams.blockLen = this->dBytes;
256	            copyParams.dstStride = 0;
257	            if (this->layout == LAYOUT_BSND) {
258	                copyParams.srcStride = (this->bcSecondDim - 1) * this->dBytes;  // layout = BSND
259	            } else {
260	                copyParams.srcStride = (this->bnSize - 1) * this->dBytes;  // layout = SBND
261	            }
262	            DataCopyPad(xLocal, xGm[xStartOffset], copyParams, this->noPadParams);
263	        }
264	    } else {
265	        if (this->layout == LAYOUT_BNSD || this->layout == LAYOUT_NO_BROADCAST || this->layout == LAYOUT_BND ||
266	            this->layout == LAYOUT_R_B1SD) {
267	            copyParams.blockCount = (uint16_t)(2 * sLines);
268	            copyParams.blockLen = this->halfDBytes;
269	            copyParams.srcStride = 0;
270	            copyParams.dstStride = 0;
271	            DataCopyPad(xLocal, xGm[xStartOffset], copyParams, this->noPadParams);
272	        } else if (this->layout == LAYOUT_BSND) {
273	            copyParams.blockCount = sLines;
274	            copyParams.blockLen = this->halfDBytes;
275	            copyParams.srcStride = (2 * this->bcSecondDim - 1) * this->halfDBytes;
276	            copyParams.dstStride = this->halfDPadBlocks;
277	            DataCopyPad(xLocal, xGm[xStartOffset], copyParams, this->noPadParams);
278	            DataCopyPad(
279	                xLocal[this->halfDPadLength], xGm[xStartOffset + this->halfDLength], copyParams, this->noPadParams);
280	        } else if (this->layout == LAYOUT_SBND) {
281	            copyParams.blockCount = sLines;
282	            copyParams.blockLen = this->halfDBytes;
283	            copyParams.srcStride = (2 * this->bnSize - 1) * this->halfDBytes;
284	            copyParams.dstStride = this->halfDPadBlocks;
285	            DataCopyPad(xLocal, xGm[xStartOffset], copyParams, this->noPadParams);
286	            DataCopyPad(
287	                xLocal[this->halfDPadLength], xGm[xStartOffset + this->halfDLength], copyParams, this->noPadParams);
288	        }
289	    }
290	    inQueueX.EnQue(xLocal);
291	}
292	
293	template <typename T>
294	__aicore__ inline void RotateHalf<T>::CopyOut(uint64_t yStartOffset, uint16_t sLines, uint32_t copyLength)
295	{
296	    LocalTensor<T> yLocal = outQueueY.DeQue<T>();
297	    DataCopyExtParams copyParams{};
298	
299	    if (this->isAligned == true) {
300	        copyParams.blockCount = sLines;
301	        copyParams.blockLen = this->dBytes;
302	        copyParams.srcStride = 0;
303	        if (this->layout == LAYOUT_BNSD || this->layout == LAYOUT_NO_BROADCAST || this->layout == LAYOUT_BND ||
304	            this->layout == LAYOUT_R_B1SD) {
305	            DataCopy(yGm[yStartOffset], yLocal, copyLength);
306	        } else {
307	            if (this->layout == LAYOUT_BSND) {
308	                copyParams.dstStride = (this->bcSecondDim - 1) * this->dBytes;  // layout = BSND
309	            } else {
310	                copyParams.dstStride = (this->bnSize - 1) * this->dBytes;  // layout = SBND
311	            }
312	            DataCopyPad(yGm[yStartOffset], yLocal, copyParams);
313	        }
314	    } else {
315	        if (this->layout == LAYOUT_BNSD || this->layout == LAYOUT_NO_BROADCAST || this->layout == LAYOUT_BND ||
316	            this->layout == LAYOUT_R_B1SD) {
317	            copyParams.blockCount = (uint16_t)(2 * sLines);
318	            copyParams.blockLen = this->halfDBytes;
319	            copyParams.srcStride = 0;
320	            copyParams.dstStride = 0;
321	            DataCopyPad(yGm[yStartOffset], yLocal, copyParams);
322	        } else if (this->layout == LAYOUT_BSND) {
323	            copyParams.blockCount = sLines;
324	            copyParams.blockLen = this->halfDBytes;
325	            copyParams.srcStride = this->halfDPadBlocks;
326	            copyParams.dstStride = (2 * this->bcSecondDim - 1) * this->halfDBytes;
327	            DataCopyPad(yGm[yStartOffset], yLocal, copyParams);
328	            DataCopyPad(yGm[yStartOffset + this->halfDLength], yLocal[this->halfDPadLength], copyParams);
329	        } else if (this->layout == LAYOUT_SBND) {
330	            copyParams.blockCount = sLines;
331	            copyParams.blockLen = this->halfDBytes;
332	            copyParams.srcStride = this->halfDPadBlocks;
333	            copyParams.dstStride = (2 * this->bnSize - 1) * this->halfDBytes;
334	            DataCopyPad(yGm[yStartOffset], yLocal, copyParams);
335	            DataCopyPad(yGm[yStartOffset + this->halfDLength], yLocal[this->halfDPadLength], copyParams);
336	        }
337	    }
338	    outQueueY.FreeTensor(yLocal);
339	}
340	
341	template <typename T>
342	__aicore__ inline void RotateHalf<T>::Compute(
343	    LocalTensor<T> &cos, LocalTensor<T> &sin, uint32_t sLines, uint32_t calcLength)
344	{
345	    LocalTensor<T> xLocal = inQueueX.DeQue<T>();
346	    LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
347	    this->XNewCopy(xLocal, yLocal, sLines);
348	    this->ComputeInner(xLocal, yLocal, cos, sin, calcLength);
349	    outQueueY.EnQue(yLocal);
350	    inQueueX.FreeTensor<T>(xLocal);
351	}
