11	/*!
12	 * \file ai_infra_rotary_position_embedding.cpp
13	 * \brief
14	 */
15	#include "ai_infra_rotate_half.h"
16	#include "ai_infra_rotate_half_bf16.h"
17	#include "ai_infra_rotate_half_rope_fullLoad_xd.h"
18	
19	using namespace AscendC;
20	using namespace RotateHalfN;
21	
22	extern "C" __global__ __aicore__ void ai_infra_rotary_position_embedding(
23	    GM_ADDR x, GM_ADDR cos, GM_ADDR sin, GM_ADDR rotate, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
24	{
25	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
26	    GET_TILING_DATA(tilingData, tiling);
27	    GM_ADDR usrWorkspace = AscendC::GetUserWorkspace(workspace);
28	
29	    // FullLoadXD path: tailAxesFLBoost overrides regular tilingKey dispatch
30	    // tilingKey = TILING_KEY_PREFIX + tilingMode * TILING_MODE_WEIGHT + tilingDtype
31	    // Dispatch by tilingKey, dtype determined by last digit: 1=FP32, 2=FP16, 3=BF16
32	
33	    // FullLoadXD path: tilingKey(11xx)
34	    if (TILING_KEY_IS(1111) || TILING_KEY_IS(1121) || TILING_KEY_IS(1131) || TILING_KEY_IS(1141) ||
35	        TILING_KEY_IS(1151) || TILING_KEY_IS(1161)) {
36	        RotateHalfRopeFullLoadXd<float, float> op;
37	        op.Init(x, cos, sin, y, tilingData);
38	        op.Process();
39	    } else if (TILING_KEY_IS(1112) || TILING_KEY_IS(1122) || TILING_KEY_IS(1132) || TILING_KEY_IS(1142) ||
40	               TILING_KEY_IS(1152) || TILING_KEY_IS(1162)) {
41	        RotateHalfRopeFullLoadXd<half, float> op;
42	        op.Init(x, cos, sin, y, tilingData);
43	        op.Process();
44	    } else if (TILING_KEY_IS(1113) || TILING_KEY_IS(1123) || TILING_KEY_IS(1133) || TILING_KEY_IS(1143) ||
45	               TILING_KEY_IS(1153) || TILING_KEY_IS(1163)) {
46	        RotateHalfRopeFullLoadXd<bfloat16_t, float> op;
47	        op.Init(x, cos, sin, y, tilingData);
48	        op.Process();
